class Solution {
public:
    int longestArithSeqLength(vector<int>& nums) {
        int n = nums.size();
        if (n <= 2) return n;
        vector<vector<int>> dp(n, vector<int>(1001, 0));
        int ans = 2;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                int d = nums[i] - nums[j] + 500;
                int prev = dp[j][d] > 0 ? dp[j][d] : 1;
                if (prev + 1 > dp[i][d]) dp[i][d] = prev + 1;
                if (dp[i][d] > ans) ans = dp[i][d];
            }
        }
        return ans;
    }
};
